-- Generated from js/player-name-unicode-15-1.js.
-- The range and sequence counts are checked by the repository tests.
-- Unicode 15.1.0; contract player-name-v1.
-- ranges: forbidden=721, space=7, variation_selector=4, join_control=1, mark=310, letter=660, nonspacing_mark=346, nonzero_ccc_mark=183, virama=56, vowel_dependent=137, joining_left_or_dual=75, joining_right_or_dual=47, joining_transparent=356
-- scripts=751, emoji_vs=219, emoji_zwj=1468

create table if not exists private.sainome_v2_unicode_ranges (
  range_kind text not null check (range_kind in (
    'forbidden', 'space', 'variation_selector', 'join_control', 'mark',
    'letter', 'nonspacing_mark', 'nonzero_ccc_mark', 'virama', 'vowel_dependent',
    'joining_left_or_dual', 'joining_right_or_dual', 'joining_transparent'
  )),
  range_start integer not null check (range_start between 0 and 1114111),
  range_end integer not null check (range_end between range_start and 1114111),
  primary key (range_kind, range_start, range_end)
);

create index if not exists sainome_v2_unicode_ranges_lookup_idx
  on private.sainome_v2_unicode_ranges (range_kind, range_start, range_end);

create table if not exists private.sainome_v2_unicode_scripts (
  range_start integer not null check (range_start between 0 and 1114111),
  range_end integer not null check (range_end between range_start and 1114111),
  script_id smallint not null check (script_id between 0 and 160),
  primary key (range_start, range_end, script_id)
);

create index if not exists sainome_v2_unicode_scripts_lookup_idx
  on private.sainome_v2_unicode_scripts (range_start, range_end);

create table if not exists private.sainome_v2_unicode_sequences (
  sequence_kind text not null check (sequence_kind in ('emoji_vs', 'emoji_zwj')),
  sequence_codepoints integer[] not null check (
    cardinality(sequence_codepoints) between 1 and 32
  ),
  primary key (sequence_kind, sequence_codepoints)
);

alter table private.sainome_v2_unicode_ranges enable row level security;
alter table private.sainome_v2_unicode_scripts enable row level security;
alter table private.sainome_v2_unicode_sequences enable row level security;

revoke all on table
  private.sainome_v2_unicode_ranges,
  private.sainome_v2_unicode_scripts,
  private.sainome_v2_unicode_sequences
from public, anon, authenticated, service_role;


