create or replace function private.sainome_v2_codepoint_in_range(
  p_range_kind text,
  p_codepoint integer
)
returns boolean
language sql
stable
set search_path = ''
as $$
  select exists (
    select 1
    from private.sainome_v2_unicode_ranges
    where range_kind = p_range_kind
      and p_codepoint between range_start and range_end
  );
$$;

create or replace function private.sainome_v2_script_for(
  p_codepoint integer
)
returns smallint
language sql
stable
set search_path = ''
as $$
  select script_id
  from private.sainome_v2_unicode_scripts
  where p_codepoint between range_start and range_end
  order by range_start
  limit 1;
$$;

create or replace function private.sainome_v2_codepoints(
  p_value text
)
returns integer[]
language plpgsql
stable
set search_path = ''
as $$
declare
  v_index integer;
  v_length integer;
  v_codepoints integer[] := array[]::integer[];
begin
  if p_value is null then
    return null;
  end if;
  v_length := char_length(p_value);
  for v_index in 1..v_length loop
    v_codepoints := array_append(
      v_codepoints,
      ascii(substr(p_value, v_index, 1))
    );
  end loop;
  return v_codepoints;
end;
$$;

create or replace function private.sainome_v2_sequence_has_valid_match(
  p_codepoints integer[],
  p_sequence integer[]
)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_start integer;
  v_sequence_length integer := cardinality(p_sequence);
  v_point_length integer := cardinality(p_codepoints);
begin
  if v_sequence_length is null or v_sequence_length = 0
     or v_point_length is null or v_point_length < v_sequence_length then
    return false;
  end if;
  for v_start in 1..(v_point_length - v_sequence_length + 1) loop
    if p_codepoints[v_start:v_start + v_sequence_length - 1] = p_sequence
       and (v_start = 1 or p_codepoints[v_start - 1] <> 8205)
       and (
         v_start + v_sequence_length - 1 = v_point_length
         or p_codepoints[v_start + v_sequence_length] <> 8205
       ) then
      return true;
    end if;
  end loop;
  return false;
end;
$$;

create or replace function private.sainome_v2_has_registered_sequence(
  p_codepoints integer[],
  p_sequence_kind text,
  p_target_codepoint integer default null
)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_sequence integer[];
begin
  for v_sequence in
    select sequence_codepoints
    from private.sainome_v2_unicode_sequences
    where sequence_kind = p_sequence_kind
      and (
        p_target_codepoint is null
        or p_target_codepoint = any(sequence_codepoints)
      )
  loop
    if private.sainome_v2_sequence_has_valid_match(p_codepoints, v_sequence) then
      return true;
    end if;
  end loop;
  return false;
end;
$$;

create or replace function private.sainome_v2_has_single_script(
  p_codepoints integer[],
  p_start integer,
  p_end integer
)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_index integer;
  v_expected smallint := null;
  v_script smallint;
begin
  if p_start < 1 or p_end < p_start
     or p_end > cardinality(p_codepoints) then
    return false;
  end if;
  for v_index in p_start..p_end loop
    v_script := private.sainome_v2_script_for(p_codepoints[v_index]);
    if v_script is null then
      continue;
    end if;
    if v_expected is null then
      v_expected := v_script;
    elsif v_expected <> v_script then
      return false;
    end if;
  end loop;
  return true;
end;
$$;

create or replace function private.sainome_v2_has_cursive_zwnj_context(
  p_codepoints integer[],
  p_index integer
)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_left integer := p_index - 1;
  v_right integer := p_index + 1;
  v_length integer := cardinality(p_codepoints);
begin
  while v_left >= 1
    and private.sainome_v2_codepoint_in_range('joining_transparent', p_codepoints[v_left]) loop
    v_left := v_left - 1;
  end loop;
  while v_right <= v_length
    and private.sainome_v2_codepoint_in_range('joining_transparent', p_codepoints[v_right]) loop
    v_right := v_right + 1;
  end loop;
  return private.sainome_v2_codepoint_in_range(
           'joining_left_or_dual', p_codepoints[v_left]
         )
     and private.sainome_v2_codepoint_in_range(
           'joining_right_or_dual', p_codepoints[v_right]
         )
     and private.sainome_v2_has_single_script(p_codepoints, v_left, v_right);
end;
$$;

create or replace function private.sainome_v2_has_conjunct_zwnj_context(
  p_codepoints integer[],
  p_index integer
)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_length integer := cardinality(p_codepoints);
  v_letter integer := p_index + 1;
  v_virama integer := p_index - 1;
  v_start integer;
begin
  while v_letter <= v_length
    and private.sainome_v2_codepoint_in_range('nonzero_ccc_mark', p_codepoints[v_letter]) loop
    v_letter := v_letter + 1;
  end loop;
  if v_letter > v_length
     or not private.sainome_v2_codepoint_in_range('letter', p_codepoints[v_letter]) then
    return false;
  end if;
  while v_virama >= 1
    and private.sainome_v2_codepoint_in_range('nonzero_ccc_mark', p_codepoints[v_virama]) loop
    if private.sainome_v2_codepoint_in_range('virama', p_codepoints[v_virama]) then
      v_start := v_virama - 1;
      while v_start >= 1
        and private.sainome_v2_codepoint_in_range('nonspacing_mark', p_codepoints[v_start]) loop
        v_start := v_start - 1;
      end loop;
      if v_start >= 1
         and private.sainome_v2_codepoint_in_range('letter', p_codepoints[v_start])
         and private.sainome_v2_has_single_script(
           p_codepoints, v_start, v_letter
         ) then
        return true;
      end if;
    end if;
    v_virama := v_virama - 1;
  end loop;
  return false;
end;
$$;

create or replace function private.sainome_v2_has_conjunct_zwj_context(
  p_codepoints integer[],
  p_index integer
)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_virama integer := p_index - 1;
  v_start integer;
begin
  if private.sainome_v2_codepoint_in_range(
       'vowel_dependent', p_codepoints[p_index + 1]
     ) then
    return false;
  end if;
  while v_virama >= 1
    and private.sainome_v2_codepoint_in_range('nonzero_ccc_mark', p_codepoints[v_virama]) loop
    if private.sainome_v2_codepoint_in_range('virama', p_codepoints[v_virama]) then
      v_start := v_virama - 1;
      while v_start >= 1
        and private.sainome_v2_codepoint_in_range('nonspacing_mark', p_codepoints[v_start]) loop
        v_start := v_start - 1;
      end loop;
      if v_start >= 1
         and private.sainome_v2_codepoint_in_range('letter', p_codepoints[v_start])
         and private.sainome_v2_has_single_script(
           p_codepoints, v_start, p_index
         ) then
        return true;
      end if;
    end if;
    v_virama := v_virama - 1;
  end loop;
  return false;
end;
$$;

create or replace function private.sainome_v2_has_valid_join_contexts(
  p_codepoints integer[]
)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_index integer;
  v_length integer := cardinality(p_codepoints);
  v_codepoint integer;
begin
  for v_index in 1..v_length loop
    v_codepoint := p_codepoints[v_index];
    if private.sainome_v2_codepoint_in_range(
         'variation_selector', v_codepoint
       ) then
      if not private.sainome_v2_has_registered_sequence(
        p_codepoints, 'emoji_vs', v_codepoint
      ) and not private.sainome_v2_has_registered_sequence(
        p_codepoints, 'emoji_zwj', v_codepoint
      ) then
        return false;
      end if;
    elsif v_codepoint = 8205 then
      if not private.sainome_v2_has_registered_sequence(
        p_codepoints, 'emoji_zwj', 8205
      ) and not private.sainome_v2_has_conjunct_zwj_context(
        p_codepoints, v_index
      ) then
        return false;
      end if;
    elsif v_codepoint = 8204 then
      if not private.sainome_v2_has_cursive_zwnj_context(
        p_codepoints, v_index
      ) and not private.sainome_v2_has_conjunct_zwnj_context(
        p_codepoints, v_index
      ) then
        return false;
      end if;
    end if;
  end loop;
  return true;
end;
$$;

create or replace function private.sainome_v2_has_valid_mark_contexts(
  p_name text
)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_points integer[] := private.sainome_v2_codepoints(normalize(p_name, NFD));
  v_index integer;
  v_codepoint integer;
  v_cluster_has_base boolean := false;
  v_mark_count integer := 0;
  v_seen_marks integer[] := array[]::integer[];
begin
  for v_index in 1..cardinality(v_points) loop
    v_codepoint := v_points[v_index];
    if private.sainome_v2_codepoint_in_range(
         'space', v_codepoint
       ) then
      v_cluster_has_base := false;
      v_mark_count := 0;
      v_seen_marks := array[]::integer[];
      continue;
    end if;
    if private.sainome_v2_codepoint_in_range(
         'variation_selector', v_codepoint
       ) or private.sainome_v2_codepoint_in_range(
         'join_control', v_codepoint
       ) then
      continue;
    end if;
    if private.sainome_v2_codepoint_in_range(
         'mark', v_codepoint
       ) then
      if not v_cluster_has_base
         or v_mark_count >= 4
         or v_codepoint = any(v_seen_marks) then
        return false;
      end if;
      v_mark_count := v_mark_count + 1;
      v_seen_marks := array_append(v_seen_marks, v_codepoint);
      continue;
    end if;
    v_cluster_has_base := true;
    v_mark_count := 0;
    v_seen_marks := array[]::integer[];
  end loop;
  return true;
end;
$$;

create or replace function private.sainome_v2_validate_name(p_name text)
returns text
language plpgsql
stable
set search_path = ''
as $$
declare
  v_points integer[];
  v_index integer;
  v_codepoint integer;
  v_visible_base boolean := false;
begin
  if p_name is null then
    raise exception 'ranking name is null' using errcode = '22023';
  end if;
  if char_length(p_name) < 1 or char_length(p_name) > 20 then
    raise exception 'ranking name length is invalid' using errcode = '22023';
  end if;
  if p_name <> normalize(p_name, NFKC)
     or p_name ~ '(^ | $|  )' then
    raise exception 'ranking name is not canonical' using errcode = '22023';
  end if;
  v_points := private.sainome_v2_codepoints(p_name);
  for v_index in 1..cardinality(v_points) loop
    v_codepoint := v_points[v_index];
    if private.sainome_v2_codepoint_in_range(
         'forbidden', v_codepoint
       ) then
      raise exception 'ranking name contains an invisible or invalid character' using errcode = '22023';
    end if;
    if private.sainome_v2_codepoint_in_range(
         'space', v_codepoint
       ) and v_codepoint <> 32 then
      raise exception 'ranking name contains a non-canonical space' using errcode = '22023';
    end if;
    if not private.sainome_v2_codepoint_in_range(
         'space', v_codepoint
       ) and not private.sainome_v2_codepoint_in_range(
         'mark', v_codepoint
       ) and not private.sainome_v2_codepoint_in_range(
         'variation_selector', v_codepoint
       ) and not private.sainome_v2_codepoint_in_range(
         'join_control', v_codepoint
       ) then
      v_visible_base := true;
    end if;
  end loop;
  if not v_visible_base then
    raise exception 'ranking name has no visible base' using errcode = '22023';
  end if;
  if not private.sainome_v2_has_valid_join_contexts(v_points)
     or not private.sainome_v2_has_valid_mark_contexts(p_name) then
    raise exception 'ranking name has an invalid join or mark context' using errcode = '22023';
  end if;
  return p_name;
end;
$$;

